// Normalizes the inbound review payload from your Zapier 'New Review' zap (or any reputation
// tool that can POST JSON). See the deploy guide for the exact field names to map in Zapier.
//
// Star rating may arrive as a number (1-5) or Google's word form (ONE..FIVE) -- Google's own API,
// and therefore Zapier's Google Business Profile trigger, use the word form.
const raw  = $input.first().json;
const body = raw.body || raw;

const RATING_WORDS = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
let ratingRaw = body.star_rating ?? body.rating ?? body.starRating;
let rating;
if (typeof ratingRaw === 'string') {
  const upper = ratingRaw.trim().toUpperCase();
  rating = RATING_WORDS[upper] ?? parseInt(ratingRaw, 10);
} else {
  rating = Number(ratingRaw);
}

const review_id     = String(body.review_id || body.reviewId || '').trim();
const reviewer_name = String(body.reviewer_name || body.reviewerName || 'A reviewer').trim();
const review_text   = String(body.review_text || body.comment || '').trim();
const review_url    = String(body.review_url || body.reviewUrl || '').trim();
const location_name = String(body.location_name || body.locationName || '').trim();
const created_at    = String(body.created_at || body.createTime || new Date().toISOString()).trim();

const is_valid_review    = !!review_id && Number.isInteger(rating) && rating >= 1 && rating <= 5;
const is_negative_review = is_valid_review && rating < 4;

return [{ json: {
  review_id, reviewer_name, review_text, review_url, location_name, created_at,
  rating, is_valid_review, is_negative_review, received_at: new Date().toISOString(),
} }];

// Dedupes on review_id using n8n's built-in workflow static data -- no external database or
// lookup call needed. Zapier can redeliver the same 'New Review' trigger, and Google re-fires
// the trigger if a review is edited -- both would otherwise alert the firm twice for one review.
// Self-prunes entries older than 30 days so static data doesn't grow unbounded.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.seenReviews) staticData.seenReviews = {};

const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;
const now = Date.now();

for (const [id, seenAt] of Object.entries(staticData.seenReviews)) {
  if (now - seenAt > THIRTY_DAYS_MS) delete staticData.seenReviews[id];
}

const is_duplicate = !!staticData.seenReviews[item.review_id];
if (!is_duplicate) staticData.seenReviews[item.review_id] = now;

return [{ json: { ...item, is_duplicate } }];

// Reads firm config from n8n Variables and builds the instant SMS alert text plus the Claude
// prompt for the draft public reply. See the deploy guide for what each Variable should contain.
const FIRM_NAME          = $vars.FIRM_NAME;
const FIRM_EMAIL         = $vars.FIRM_EMAIL;
const FROM_EMAIL         = $vars.FIRM_FROM_EMAIL;
const ALERT_PHONE        = $vars.FIRM_ALERT_PHONE;        // firm's own cell -- NOT the reviewer's number
const FIRM_TWILIO_NUMBER = $vars.FIRM_TWILIO_NUMBER;
const GBP_DASHBOARD_URL  = $vars.FIRM_GBP_DASHBOARD_URL;  // fallback reply link if Zapier didn't send one

if (!FIRM_NAME)  throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_EMAIL) throw new Error('FIRM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it (can be the same as FIRM_EMAIL).');

const item = $input.first().json;
const replyLink = item.review_url || GBP_DASHBOARD_URL || '';

const preview = item.review_text.length > 100
  ? item.review_text.slice(0, 100) + '…'
  : item.review_text;

const smsAlert = `⚠ New ${item.rating}-star Google review${item.location_name ? ' at ' + item.location_name : ''}. From ${item.reviewer_name}: "${preview}" A draft reply is on its way to your email. Responding within 24h roughly triples your odds of turning this around.`;

const prompt = `You are drafting a public reply to a negative Google Business Profile review for ${FIRM_NAME}, a law firm. Draft ONE short public reply, following every rule below without exception — these rules exist because responding incorrectly can violate attorney ethics rules (ABA Formal Opinion 496) and client confidentiality:

- Do NOT confirm, deny, or imply that the reviewer is or was a client of the firm, or that any attorney-client relationship exists or existed.
- Do NOT reference, confirm, or dispute any facts about a specific case, matter, representation, or outcome — even to correct the reviewer's account of events.
- Do NOT disclose any information that could identify a client or matter.
- Do NOT admit fault, apologize for a specific outcome, or make any statement that could be read as a legal admission.
- Do NOT provide legal advice, legal opinions, or commentary on the reviewer's legal situation.
- Keep it to 2-4 sentences, calm, professional, and non-defensive.
- Thank the reviewer for their feedback in general terms, note that the firm takes all feedback seriously, and invite them to contact the firm directly and privately (phone or email) to discuss their concerns.
- Never argue, never get defensive.

Reviewer's review (${item.rating} out of 5 stars): "${item.review_text}"

Return ONLY a valid JSON object — no markdown fences, no preamble. Keys required:
- draft_response: the public reply text described above
- is_response_safe: true
If you cannot draft a safe reply without violating a rule above, return only: {"is_response_safe": false, "safety_note": "brief reason"}`;

return [{ json: {
  ...item,
  firm_name:          FIRM_NAME,
  firm_email:         FIRM_EMAIL,
  from_email:         FROM_EMAIL,
  alert_phone:        ALERT_PHONE,
  firm_twilio_number: FIRM_TWILIO_NUMBER,
  reply_link:         replyLink,
  sms_alert:          smsAlert,
  claude_request: {
    model:      'claude-sonnet-4-6',
    max_tokens: 400,
    messages:   [{ role: 'user', content: prompt }],
  },
} }];

// Parses Claude's JSON response and runs an independent post-hoc keyword scan for anything that
// would violate attorney-client confidentiality or ABA Formal Opinion 496 -- Claude's self-report
// is Layer 1, this scan is Layer 2. is_response_safe is true only if both layers pass.
const prep = $('Prepare Alert And Draft Prompt').item.json;

const rawResponse = $input.first().json;
const rawText = (rawResponse.content && rawResponse.content[0] && rawResponse.content[0].text)
  ? rawResponse.content[0].text.trim()
  : '';

if (!rawText) {
  throw new Error('Claude API returned an empty response. Check the Anthropic API key, usage quota, and rate limits at console.anthropic.com.');
}

let parsed;
try {
  const cleaned = rawText.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude did not return valid JSON. Raw response: ' + rawText.slice(0, 400));
}

let draft_response   = '';
let is_response_safe = false;
let safety_note      = '';

if (parsed.is_response_safe === false) {
  safety_note = parsed.safety_note || 'Claude flagged this review as unsafe to draft a public reply for.';
} else {
  draft_response = String(parsed.draft_response || '').trim();

  // Layer 2 -- confidentiality / representation / admission language that should never appear
  // in a public reply, even if Claude's self-check missed it.
  const UNSAFE_RE = /\b(our client|you were (our|a) client|as (your|our) (attorney|lawyer)|attorney.client|represented you|your case|your matter|on your behalf|we apologi[sz]e for (the|your) outcome|admit|at fault|our fault|malpractice|settlement amount)\b/i;
  const flagged = UNSAFE_RE.test(draft_response) || !draft_response;

  is_response_safe = !flagged;
  if (flagged) safety_note = 'Post-hoc scan found confidentiality- or representation-confirming language in the draft.';
}

const statusLabel = is_response_safe ? 'DRAFT READY TO POST' : 'DRAFT NEEDS A HUMAN REWRITE';
const DIV = '─'.repeat(60);

const email_subject = `${prep.rating}-star review alert — ${prep.location_name || prep.firm_name} — ${statusLabel}`;

const email_body = [
  `New ${prep.rating}-star Google review — respond within 24 hours for the best chance of turning this around (firms that do convert roughly 33% of these to neutral or positive).`,
  '',
  `Reviewer: ${prep.reviewer_name}`,
  `Received: ${prep.created_at}`,
  prep.reply_link ? `Reply here: ${prep.reply_link}` : 'Reply here: log into Google Business Profile → Reviews.',
  '',
  DIV,
  'REVIEWER WROTE',
  DIV,
  prep.review_text || '(no text — star rating only)',
  '',
  DIV,
  `SUGGESTED REPLY — ${statusLabel}`,
  DIV,
  is_response_safe ? draft_response : `(No safe draft available — ${safety_note} Write the reply yourself, following your firm's standard rule: never confirm a client relationship, never reference case facts, never admit fault.)`,
  '',
  DIV,
  'BEFORE YOU POST',
  '• Never confirm or deny that the reviewer is or was a client',
  '• Never reference case facts, even to correct the reviewer',
  '• Keep it brief, calm, and non-defensive',
  '• When in doubt, invite them to call or email the firm privately instead of replying further in public',
  `Generated: ${new Date().toISOString()}`,
].join('\n');

return [{ json: {
  ...prep,
  draft_response,
  is_response_safe,
  safety_note,
  email_subject,
  email_body,
} }];
